    client='/opt/sting-aisoc-socai2/investigation-v2/20261101-r11/scripts/investigation_client.py'
    def get(tenant,path,label,expected=200):
        response=subprocess.run([sys.executable,'-B',client,'GET',path,'--timeout','20'],capture_output=True,timeout=30,env={**os.environ,'AISOC_API_TOKEN':tokens[tenant]})
        match=re.search(rb'HTTP (\d+)',response.stderr);status=int(match.group(1)) if match else None
